sys_variable_value.value:
(function(outputs, steps, params, stepResult, assertEqual) {
    var testCases = [
        'My order arrived 45 minutes late and two items were missing.',
        'One of the products I received was slightly damaged.',
        'My order has been delayed for over an hour and this has happened three times this week.',
        'I was charged twice for the same order.',
        'There is a serious safety issue at the store and customers are being exposed to a dangerous condition.',
        'The packaging was slightly messy but everything arrived correctly.',
        'The food arrived spoiled and I became sick after eating it.',
        'This is absolutely unacceptable. My order is over two hours late and this has ruined an important event.',
        'My payment failed several times and I was charged but never received confirmation for the order.',
        'Everything was fine with my order. Thank you.'
    ];

    var createdIds = [];
    var results = [];

    for (var i = 0; i < testCases.length; i++) {
        var gr = new GlideRecord('sn_customerservice_case');
        gr.initialize();
        gr.setValue('short_description', testCases[i]);
        var sysId = gr.insert();
        if (sysId) {
            createdIds.push(sysId);
            // Re-read the record to get the AI-populated fields
            var check = new GlideRecord('sn_customerservice_case');
            if (check.get(sysId)) {
                results.push({
                    id: sysId,
                    input: testCases[i],
                    category: check.getValue('x_2145749_qc_complaint_type') || '',
                    score: check.getValue('x_2145749_qc_ai_urgency_score') || '',
                    level: check.getValue('x_2145749_qc_ai_urgency_level') || '',
                    reason: check.getValue('x_2145749_qc_ai_urgency_reason') || ''
                });
            }
        } else {
            results.push({ id: '', input: testCases[i], error: 'INSERT FAILED' });
        }
    }

    outputs.created_count = createdIds.length;
    outputs.results_json = JSON.stringify(results);
    outputs.created_ids = createdIds.join(',');
    stepResult.setOutputMessage('Created ' + createdIds.length + ' cases. Results: ' + JSON.stringify(results, null, 2));

    assertEqual({ name: 'All 10 cases created', shouldbe: '10', value: String(createdIds.length) });
})(outputs, steps, params, stepResult, assertEqual);
